import{_ as a,o as d,c as r,a2 as $}from"./chunks/framework.F7eQ-ohH.js";const p="/bzygq/assets/quesion_imgs_56e73fbcfab54dd8b87083e3edb2af83.CiVYLrhT.png",e="/bzygq/assets/quesion_imgs_a8104fdb96bc42d49693bce26c76a9a6.CQfXM8P3.png",c="/bzygq/assets/quesion_imgs_36b41f8cf67649b49945582e1141e613.BPBCJjyi.png",o="/bzygq/assets/quesion_imgs_4c686541d3af4e6d81ba99c9ccd7c87c.Ds_JpCPI.png",s="/bzygq/assets/quesion_imgs_aadbd76d2d3a47b1ab91b505f42219c2.HA0RCh-f.png",m=JSON.parse('{"title":"速算技巧","description":"","frontmatter":{},"headers":[],"relativePath":"行测/资料分析/8.速算技巧.md","filePath":"行测/资料分析/8.速算技巧.md","lastUpdated":1788883925000}'),i={name:"行测/资料分析/8.速算技巧.md"};function l(n,t,h,f,b,_){return d(),r("div",null,[...t[0]||(t[0]=[$('<h1 id="速算技巧" tabindex="-1"><strong>速算技巧</strong> <a class="header-anchor" href="#速算技巧" aria-label="Permalink to &quot;**速算技巧**&quot;">​</a></h1><h2 id="首数法" tabindex="-1">首数法 <a class="header-anchor" href="#首数法" aria-label="Permalink to &quot;首数法&quot;">​</a></h2><p><img src="'+p+'" alt=""></p><p><strong>例1、75131.6+14722.1=（）</strong></p><p>A.89853.7</p><p>B.88753.7</p><p>C.87633.7</p><p>D.90443.7</p><p>解析：选项中的前2个数字各不相同，因此可以考虑使用首数法，题目中前两位数字相加和为75+14=89，第三位有效数字相加1+7&lt;10不涉及进位，因此答案直接可以得出选A。</p><p><strong>例2、52314.68/8431.25 = ()</strong></p><p>A.5.3</p><p>B.4.7</p><p>C.7.3</p><p>D.6.2</p><p>解析：上面的计算可以近似化简为，约为6.X，所以答案选D。</p><h2 id="尾数法" tabindex="-1">尾数法 <a class="header-anchor" href="#尾数法" aria-label="Permalink to &quot;尾数法&quot;">​</a></h2><p><img src="'+e+'" alt=""></p><p><strong>例1、356.73+137.81-224.1+34.52=（）</strong></p><p>A.287.67</p><p>B.304.96</p><p>C.311.64</p><p>D.297.95</p><p>解析：选项末位数字各不相同，考虑尾数法，先加后减，尾数和相加为(3+2+1)-0=6 ，因此答案选择B。</p><h2 id="估算法" tabindex="-1">估算法 <a class="header-anchor" href="#估算法" aria-label="Permalink to &quot;估算法&quot;">​</a></h2><p>“估算法”是资料分析题当中的速算第一法，在所有计算进行之前必须考虑能否先行估算。所谓估算，是在精度要求并不太高的情况下，进行粗略估值的速算方式。一般在选项相差较大，或者在被比较数据相差较大的情况下使用。估算的方式多样，需要各位考生在实战中多加训练与掌握。进行估算的前提是选项或者待比较的数字相差必须比较大，并且这个差别的大小决定了“估算”时候的精度要求。</p><p><strong>例1、根据材料，下列年份中该企业销售额增幅最高的年份为：</strong></p><p><img src="'+c+'" alt=""></p><p>A.2002 年</p><p>B.2003 年</p><p>C.2004 年</p><p>D.2005 年</p><p>答案：A</p><p>解析： 估算可看出 2002 年增幅大于 1 倍，其它不到 1 倍，故选 A。</p><h2 id="有效数字法" tabindex="-1">有效数字法 <a class="header-anchor" href="#有效数字法" aria-label="Permalink to &quot;有效数字法&quot;">​</a></h2><p>有效数字法，是指“在精度允许的范围内，将计算过程当中的数字截位（即只看或者只取前几位），从而得到精度足够的计算结果”的速算方式。</p><p><img src="'+o+'" alt=""></p><p>在加法或者减法中使用“有效数字法”时，直接从左边高位开始相加或者相减（同时注意下一位是否需要进位与借位），直到得到选项要求精度的答案为止在乘法或者除法中使用“有效数字法”时，为了使所得结果 尽可能精确，需要注意截位近似的方向。</p><p><strong>例1、根据材料回答问题，2002 年 SCI 收录文章中，美国占 32.17％，则我国约占（ ）。</strong></p><p><img src="'+s+'" alt=""></p><p>A. 2％</p><p>B. 3％</p><p>C. 4％</p><p>D. 5％</p><p>答案：C</p><p>**解析：**美国 313613 占 32.17%，中国 40758 占 x, 313613÷32.17=40758÷x,x=40758×32÷313613 ≈40000×32÷320000=4,故选 C。</p><h2 id="比较大小" tabindex="-1">比较大小 <a class="header-anchor" href="#比较大小" aria-label="Permalink to &quot;比较大小&quot;">​</a></h2><h2 id="差分法" tabindex="-1">差分法 <a class="header-anchor" href="#差分法" aria-label="Permalink to &quot;差分法&quot;">​</a></h2><p>行测差分法是一种用于比较两个分数大小的方法，尤其适用于两个分数的分子和分母都比较接近的情况。差分法可以将不易直接比较大小的两个分数，转化为比较差分数和小分数的大小，在很多情况下能够简化比较过程，提高解题速度。</p><p>对于两个分数$$\\frac{a}{b}$$和$$\\frac{c}{d}$$（a、b、c、d均为正数），如果$$a\\gt c$$且$$b\\gt d$$，那么我们称$$\\frac{a - c}{b - d}$$为$$\\frac{a}{b}$$和$$\\frac{c}{d}$$的差分数，$$\\frac{a}{b}$$为大分数，$$\\frac{c}{d}$$为小分数</p><p>若差分数大于小分数，则大分数大于小分数；若差分数小于小分数，则大分数小于小分数；若差分数等于小分数，则大分数等于小分数。</p><p>例1、比较$$\\frac{31}{37}$$和$$\\frac{29}{34}$$的大小。 解析：</p><ul><li>首先计算差分数：$$\\frac{31 - 29}{37 - 34}=\\frac{2}{3}$$。</li><li>然后比较差分数$$\\frac{2}{3}$$和小分数$$\\frac{29}{34}$$的大小。为了方便比较，将两个分数通分，$$\\frac{2}{3}=\\frac{68}{102}$$，$$\\frac{29}{34}=\\frac{87}{102}$$。因为$$\\frac{68}{102}\\lt\\frac{87}{102}$$，即差分数小于小分数，所以大分数$$\\frac{31}{37}$$小于小分数$$\\frac{29}{34}$$。</li></ul><h2 id="同位比较法" tabindex="-1">同位比较法 <a class="header-anchor" href="#同位比较法" aria-label="Permalink to &quot;同位比较法&quot;">​</a></h2><p>行测同位比较法是用于比较两个或多个分数大小的一种方法，尤其适用于分子分母都较大且数据较为复杂的分数。以下是具体介绍：同位比较法的核心是通过比较相同位置上数字的变化幅度来判断分数的大小关系。对于两个分数$$\\frac{A}{B}$$和$$\\frac{C}{D}$$，可以分别比较分子和分母的变化情况。</p><ol><li>若分子的增长幅度大于分母的增长幅度，则分数值变大；</li><li>若分子的增长幅度小于分母的增长幅度，则分数值变小；</li><li>若分子分母增长幅度相同，则分数值不变。</li></ol><h3 id="横向比较" tabindex="-1">横向比较 <a class="header-anchor" href="#横向比较" aria-label="Permalink to &quot;横向比较&quot;">​</a></h3><p>当两个分数的分子和分母都按同一方向变化（同为增大或同为减小）时，比较分子之间的倍数关系与分母之间的倍数关系。例如，比较$$\\frac{32}{25}$$和$$\\frac{48}{30}$$，分子从 32 到 48，是$$48\\div32 = 1.5$$倍；分母从 25 到 30，是$$30\\div25 = 1.2$$倍。分子的倍数大于分母的倍数，所以$$\\frac{48}{30}\\gt\\frac{32}{25}$$。若分子分母变化方向不同，可通过将其中一个分数的分子分母同时扩大相同倍数，使分子或分母的变化方向一致后再进行比较。</p><h3 id="纵向比较" tabindex="-1">纵向比较 <a class="header-anchor" href="#纵向比较" aria-label="Permalink to &quot;纵向比较&quot;">​</a></h3><p>当两个分数的分子或分母有明显的倍数关系时，可将分子或分母化为相同或相近的数进行比较。比如，比较$$\\frac{12}{25}$$和$$\\frac{24}{55}$$，可以将$$\\frac{12}{25}$$的分子分母同时乘以 2 得到$$\\frac{24}{50}$$。此时两个分数分子相同，分母$$50\\lt55$$，根据 “分子相同，分母小的分数大”，可知$$\\frac{24}{50}\\gt\\frac{24}{55}$$，即$$\\frac{12}{25}\\gt\\frac{24}{55}$$。</p><h2 id="常见百分数" tabindex="-1">常见百分数 <a class="header-anchor" href="#常见百分数" aria-label="Permalink to &quot;常见百分数&quot;">​</a></h2><table tabindex="0"><thead><tr><th>分数</th><th>百分比</th><th>分数</th><th>百分比</th><th>分数</th><th>百分比</th></tr></thead><tbody><tr><td>1/2</td><td>50.0%</td><td>1/7</td><td>14.3%</td><td>1/12</td><td>8.3%</td></tr><tr><td>1/3</td><td>33.3%</td><td>1/8</td><td>12.5%</td><td>1/13</td><td>7.7%</td></tr><tr><td>1/4</td><td>25.0%</td><td>1/9</td><td>11.1%</td><td>1/14</td><td>7.1%</td></tr><tr><td>1/5</td><td>20.0%</td><td>1/10</td><td>10.0%</td><td>1/15</td><td>6.7%</td></tr><tr><td>1/6</td><td>16.7%</td><td>1/11</td><td>9.1%</td><td>1/16</td><td>6.25%</td></tr><tr><td></td><td></td><td>1/17</td><td>5.9%</td><td>1/18</td><td>5.6%</td></tr><tr><td></td><td></td><td>1/19</td><td>5.3%</td><td>1/20</td><td>5.0%</td></tr></tbody></table>',61)])])}const u=a(i,[["render",l]]);export{m as __pageData,u as default};
